const crypto = require('crypto');

// Respuestas por palabra clave. Tono 8vobit: directo, cercano, sin emojis en exceso.
const RESPUESTAS = {
  'AGENDA': `¡Hola! Gracias por escribir a 8vobit 🔧\nPara revisar tu notebook o PC, agenda tu hora aquí: ${$env.LINK_AGENDA}\nEstamos en Freire 1458, Concepción. Si nos cuentas el modelo y qué le pasa, te damos un precio estimado antes de tocarlo.`,
  'AGENDA PRO': `¡Hola! Gracias por escribir a 8vobit.\nHacemos tu página profesional con agenda incluida: tus clientes reservan solos, a cualquier hora.\nCuéntanos a qué te dedicas y te mostramos un ejemplo. Más info: ${$env.LINK_WEB}`,
  'WEB': `¡Hola! Gracias por escribir a 8vobit.\nHacemos tu página profesional con agenda incluida: tus clientes reservan solos, a cualquier hora.\nCuéntanos a qué te dedicas y te mostramos un ejemplo. Más info: ${$env.LINK_WEB}`,
  'DEMO': `¡Hola! Gracias por escribir a 8vobit 🍔\nTe mostramos el sistema de pedidos funcionando: carta web, despacho por zonas y caja del día, por 1 % del pedido.\nPlanes y detalles: ${$env.LINK_PEDIDOS}\n¿Cómo se llama tu local y en qué sector está? Coordinamos la demo.`
};

function normalizar(s) {
  return s.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase();
}

function clasificar(texto) {
  const t = normalizar(texto);
  if (/\bAGENDA\s*PRO\b/.test(t)) return 'AGENDA PRO';
  if (/\bAGENDA\b/.test(t)) return 'AGENDA';
  if (/\bDEMO\b/.test(t)) return 'DEMO';
  if (/\bWEB\b/.test(t)) return 'WEB';
  return null;
}

const salida = [];
for (const item of $input.all()) {
  // 1) Verificar que el aviso viene de Meta (firma HMAC-SHA256 con el App Secret).
  const headers = item.json.headers || {};
  const firma = String(headers['x-hub-signature-256'] || '');
  const crudo = item.binary && item.binary.data
    ? Buffer.from(item.binary.data.data, 'base64')
    : Buffer.from(JSON.stringify(item.json.body || {}));
  const esperada = 'sha256=' + crypto.createHmac('sha256', $env.IG_APP_SECRET || '').update(crudo).digest('hex');
  if (firma.length !== esperada.length || !crypto.timingSafeEqual(Buffer.from(firma), Buffer.from(esperada))) {
    continue; // firma inválida: se ignora en silencio
  }

  // 2) Recorrer los mensajes y quedarse solo con los que traen palabra clave.
  const body = item.json.body || {};
  for (const entry of body.entry || []) {
    for (const ev of entry.messaging || []) {
      const msg = ev.message;
      if (!msg || msg.is_echo || typeof msg.text !== 'string') continue;
      const clave = clasificar(msg.text);
      if (!clave) continue; // sin palabra clave: lo contesta una persona
      salida.push({ json: {
        remitente: ev.sender && ev.sender.id,
        clave,
        texto: msg.text.slice(0, 300),
        respuesta: RESPUESTAS[clave]
      } });
    }
  }
}
return salida;
